if(s.model==='projectile'||s.model==='lorentz'){const xs=samples.map(q=>q.x),ys=samples.map(q=>q.y),xmin=Math.min(0,...xs),xmax=Math.max(...xs),ymin=Math.min(0,...ys),ymax=Math.max(...ys),scale=Math.min(425/Math.max(xmax-xmin,1e-30),235/Math.max(ymax-ymin,1e-30)),X=x=>45+(x-xmin)*scale,Y=y=>310-(y-ymin)*scale;line(40,Y(0),485,Y(0),colors.grid);ctx.strokeStyle=colors.mint;ctx.lineWidth=2;ctx.beginPath();for(let i=0;i<=100;i++){const a=problemSample(s,z.t*i/100);i?ctx.lineTo(X(a.x),Y(a.y)):ctx.moveTo(X(a.x),Y(a.y));}ctx.stroke();dot(X(z.x),Y(z.y));const vel=Math.max(p.v0||p.v,Math.hypot(z.vx,z.vy),1e-30);arrow(X(z.x),Y(z.y),45*z.vx/vel,-45*z.vy/vel,colors.blue);ctx.fillStyle=colors.muted;ctx.fillText('横、纵方向采用相同长度比例',40,342);}
else if(s.model==='pendulum'){line(200,85,200,300,colors.grid);const angle=z.values[0][1]*Math.PI/180,x=200+180*Math.sin(angle),y=90+180*Math.cos(angle);line(200,90,x,y,colors.blue,3);dot(x,y);dot(200,90,colors.orange,5);ctx.fillStyle=colors.muted;ctx.fillText('摆角按数据绘制，摆长按画面比例显示',35,342);}
else if(s.model==='rc'){line(60,120,270,120,colors.blue);line(270,120,270,265,colors.blue);line(60,265,270,265,colors.blue);line(60,120,60,265,colors.blue);line(46,182,74,182,colors.mint,4);line(50,196,70,196,colors.mint,3);ctx.fillStyle=colors.bg;ctx.fillRect(260,172,22,42);line(258,182,282,182,colors.orange,4);line(258,204,282,204,colors.orange,4);ctx.strokeStyle=colors.orange;ctx.strokeRect(140,110,50,20);ctx.fillStyle=colors.muted;ctx.fillText('R='+number(p.r)+' Ω',110,95);ctx.fillText('C='+number(p.c)+' F',270,235);const X=t=>350+130*t/total,Y=u=>300-180*u/p.u;line(350,300,480,300);line(350,95,350,300);ctx.strokeStyle=colors.mint;ctx.beginPath();for(let i=0;i<=100;i++){const a=problemSample(s,z.t*i/100);i?ctx.lineTo(X(a.t),Y(a.values[0][1])):ctx.moveTo(X(a.t),Y(a.values[0][1]));}ctx.stroke();dot(X(z.t),Y(z.values[0][1]),colors.mint,5);}
else{let all=samples.map(q=>q.x);if(s.model==='collision')all=all.concat(samples.map(q=>q.y));const lo=Math.min(0,...all),hi=Math.max(0,...all),X=x=>60+(x-lo)*390/Math.max(hi-lo,1e-20);line(45,270,485,270);if(s.model==='harmonic'){let x=50,y=250;ctx.strokeStyle=colors.blue;ctx.beginPath();ctx.moveTo(x,y);for(let i=1;i<=18;i++)ctx.lineTo(x+(X(z.x)-x-18)*i/18,y+(i%2?8:-8));ctx.lineTo(X(z.x),y);ctx.stroke();dot(X(z.x),250);}else{dot(X(z.x),250);if(s.model==='collision')dot(X(z.y),250,colors.orange);}const scale=Math.max(1,...samples.flatMap(q=>[Math.abs(q.vx),Math.abs(q.vy)]));arrow(X(z.x),235,55*z.vx/scale,0,colors.blue);ctx.fillStyle=colors.muted;ctx.fillText(s.model==='collision'?'绿色：物体 1   橙色：物体 2':'位置随具体数据计算，箭头表示速度方向',40,342);}
