const own=(object,key)=>Object.hasOwn(object,key);
const active=(f,p)=>!f.when||Object.entries(f.when).every(([key,value])=>p[key]===value);
function validateQuestion3D(candidate){
 if(!candidate||!own(question3DModels,candidate.experiment))throw Error('暂未匹配到可按本题参数驱动的 3D 实验。');
 const model=question3DModels[candidate.experiment],input=candidate.parameters;
 if(!input||typeof input!=='object'||Array.isArray(input))throw Error('题目参数无效。');
 const parameters={},assumptions=Array.isArray(candidate.assumptions)?candidate.assumptions.filter(x=>typeof x==='string').slice(0,8).map(x=>x.slice(0,300)):[];
 // Selectors first so conditional fields are validated against the actual mode.
 for(const f of [...model.fields.filter(f=>f.values),...model.fields.filter(f=>!f.values)]){
  if(!active(f,{...input,...parameters}))continue;
  let value=own(input,f.key)?input[f.key]:undefined;
  if(value===undefined&&f.defaultValue!==undefined){value=f.defaultValue;if(f.defaultNote)assumptions.push(f.defaultNote);}
  if(typeof value!=='number'||!Number.isFinite(value))throw Error('请补充'+f.label+'（'+(f.unit||'无量纲')+'）。');
  if(value<f.min||value>f.max||(f.values&&!f.values.includes(value))||(f.integer&&!Number.isInteger(value)))throw Error(f.label+'不在本站 3D 实验范围内：'+f.min+'–'+f.max+' '+f.unit+'。不会用默认值替换原题。');
  parameters[f.key]=value;
 }
 if(candidate.experiment==='incline'&&parameters.mk>parameters.ms)throw Error('动摩擦系数不能大于静摩擦系数。');
 if(candidate.experiment==='collision'&&parameters.v1<=parameters.v2)throw Error('在该初始左右位置下，v₁ 必须大于 v₂ 才会相撞。');
 if(candidate.experiment==='doubleslit'&&parameters.a>=parameters.d)throw Error('单缝宽必须小于缝间距。');
 if(candidate.experiment==='refraction'&&!((parameters.n1===1&&parameters.n2>=1.1)||(parameters.n2===1&&parameters.n1>=1.1)))throw Error('本站折射实验仅支持空气与 n=1.1–2.2 的介质之间的光路。');
 return {experiment:candidate.experiment,parameters,assumptions:[...new Set(assumptions)].slice(0,12)};
}
function normalizeQuestion3D(value){
 const none={experiment:'none',parameters:{},assumptions:[],reason:'这道题暂未匹配可带入条件的 3D 实验。',errors:[]};
 if(!value||!own(question3DModels,value.experiment))return {...none,reason:typeof value?.reason==='string'?value.reason.slice(0,600):none.reason};
 const model=question3DModels[value.experiment],parameters={},errors=[],seen=new Set();
 for(const entry of Array.isArray(value.parameters)?value.parameters:[]){
  const f=entry&&model.fields.find(f=>f.key===canonicalParameterKey(entry.key));
  if(!f){errors.push('模型返回了未支持的参数。');continue;}
  if(seen.has(f.key)){delete parameters[f.key];errors.push('模型返回了重复参数：'+f.label);continue;}
  seen.add(f.key);
  if(typeof entry.value!=='number'||!Number.isFinite(entry.value)||canonicalPhysicsUnit(entry.unit)!==f.unit){errors.push('请核对'+f.label+'的数值与单位（'+(f.unit||'无量纲')+'）。');continue;}
  parameters[f.key]=entry.value;
 }
 return {experiment:value.experiment,parameters,assumptions:Array.isArray(value.assumptions)?value.assumptions.filter(x=>typeof x==='string').slice(0,8).map(x=>x.slice(0,300)):[],reason:typeof value.reason==='string'?value.reason.slice(0,600):model.note,errors};
}
function sceneFromSimulation(simulation){
 const p=simulation?.parameters||{};let experiment,parameters;
 if(simulation?.model==='projectile'&&p.angle===0){experiment='projectile';parameters={v0:p.v0,h:p.h,g:p.g};}
 if(simulation?.model==='harmonic'){experiment='spring';parameters={m:p.m,k:p.k,A:p.amplitude,c:0};}
 if(simulation?.model==='pendulum'){experiment='pendulum';parameters={L:p.length,a:p.angle,g:p.g,b:0};}
 if(simulation?.model==='collision'){experiment='collision';parameters={m1:p.m1,m2:p.m2,v1:p.v1,v2:p.v2,e:p.e};}
 if(!experiment)return {experiment:'none',parameters:{},assumptions:[],reason:'没有与当前二维过程完全对应的可驱动三维实验。',errors:[]};
 return {experiment,parameters,assumptions:simulation.assumptions||[],reason:'参数来自本次题目解析，请先核对。',errors:[]};
}
function question3DURL(candidate,base,wrapper=false){
 const safe=validateQuestion3D(candidate);
 const url=new URL(wrapper?'./lab3d.html':`./physics-lab/experiments/${safe.experiment}.html`,base);
 if(wrapper)url.searchParams.set('experiment',safe.experiment);
 const allowedNotes=new Set(question3DModels[safe.experiment].fields.map(f=>f.defaultNote).filter(Boolean));allowedNotes.add('参数经用户核对修改，以本次参数卡数值为准。');
 // Do not put arbitrary model/student text in a shareable query string.
 url.searchParams.set('scene',JSON.stringify({experiment:safe.experiment,parameters:safe.parameters,assumptions:safe.assumptions.filter(text=>allowedNotes.has(text))}));
 return url;
}

// Only trusted packaged lab pages need inline scripts/styles and embedded WASM.
// Never apply this relaxed policy to /api/* or the AI/auth pages.
const sitePolicy = "default-src 'self'; script-src 'self'; style-src 'self'; style-src-attr 'unsafe-inline'; img-src 'self' data: blob:; connect-src 'self'; worker-src 'self'; object-src 'none'; base-uri 'self'; form-action 'self'";
const labPolicy = "default-src 'self'; script-src 'self' 'unsafe-inline' 'wasm-unsafe-eval'; style-src 'self' 'unsafe-inline'; img-src 'self' data: blob:; connect-src 'self'; font-src 'self' data:; worker-src 'self' blob:; object-src 'none'; base-uri 'self'; form-action 'self'; frame-ancestors 'self'";
function lab3dContentSecurityPolicy(pathname) {
  return pathname.startsWith('/physics-lab/') ? labPolicy : sitePolicy;
}
function staticAssetPath(pathname) {
  return pathname.endsWith('/') ? pathname + 'index.html' : pathname;
}

// Secrets and email links are server-only. Tokens are random, hashed, expiring,
// single-use, and never returned to the browser or written to application logs.
function mailConfiguration(env) {
  let origin;
  try { const url=new URL(env.PUBLIC_ORIGIN); if(url.protocol==='https:'&&!url.username&&!url.password&&url.pathname==='/') origin=url.origin; } catch {}
  return {ready:!!(env.MAIL_API_KEY&&env.MAIL_FROM&&origin),origin};
}
function escapeHTML(text) { return String(text).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
async function sendAccountEmail(env, email, kind, token) {
  const config=mailConfiguration(env);
  if(!config.ready) throw new Error('MAIL_NOT_CONFIGURED');
  const link=new URL(config.origin);
  link.searchParams.set('auth',kind==='reset'?'reset':'verify');
  link.searchParams.set('token',token);
  link.hash='home';
  const title=kind==='reset'?'重设你的密码':'验证你的邮箱';
  const interval=kind==='reset'?'30 分钟':'24 小时';
  const endpoint=new URL(env.MAIL_API_URL||'https://api.resend.com/emails');
  if(endpoint.protocol!=='https:'||endpoint.username||endpoint.password) throw new Error('INVALID_MAIL_ENDPOINT');
  const response=await fetch(endpoint,{method:'POST',redirect:'manual',headers:{'content-type':'application/json',authorization:'Bearer '+env.MAIL_API_KEY,'idempotency-key':'physics-'+kind+'-'+token.slice(0,32)},body:JSON.stringify({from:env.MAIL_FROM,to:[email],subject:'物理不愁人 · '+title,html:`<div style="font-family:system-ui;max-width:560px;margin:auto;padding:32px;color:#183c34"><h1>物理不愁人</h1><h2>${title}</h2><p>请点击下方链接，完成操作。链接在 ${interval}内有效，且只能使用一次。</p><p><a href="${escapeHTML(link.href)}" style="display:inline-block;background:#176b54;color:white;padding:14px 24px;border-radius:12px;text-decoration:none">${title}</a></p><p>如果不是你本人发起，请忽略这封邮件。请勿把链接转发给他人。</p></div>`}),signal:AbortSignal.timeout(15000)});
  if(!response.ok) throw new Error('MAIL_DELIVERY_FAILED');
}
async function issueAccountToken(env, record, kind, helpers) {
  const token=helpers.random(), now=Date.now(), ttl=kind==='reset'?1800000:86400000;
  const hash=await helpers.digest(token);
  // Persist before delivery so even an immediately opened link is usable.
  // Failed delivery removes only this token, preserving previous valid links.
  await helpers.db(env).prepare('INSERT INTO auth_tokens (token_hash,user_id,kind,expires_at) VALUES (?,?,?,?)').bind(hash,record.id,kind,now+ttl).run();
  try{await sendAccountEmail(env,record.email,kind,token);}catch(error){await helpers.db(env).prepare('DELETE FROM auth_tokens WHERE token_hash=?').bind(hash).run();throw error;}
  await helpers.db(env).prepare('DELETE FROM auth_tokens WHERE user_id=? AND kind=? AND token_hash<>?').bind(record.id,kind,hash).run();
}
async function accountMailAPI(context) {
  const {path,request,env,body,ip,json,db,digest,random,passwordHash,limited,user}=context;
  if(!['/api/forgot-password','/api/reset-password','/api/send-verification','/api/verify-email'].includes(path)) return null;
  const email=String(body.email||'').trim().toLowerCase();
  if(path==='/api/forgot-password'||path==='/api/send-verification') {
    if(!mailConfiguration(env).ready) return json({error:'邮件服务尚未配置。暂时无法发送验证或找回邮件，请联系网站管理员。',code:'MAIL_NOT_CONFIGURED'},503);
    if(!await limited(env,'mail-ip:'+ip,5,3600000)||!await limited(env,'mail-global',100,86400000)) return json({error:'发送请求过于频繁，请稍后重试。'},429);
    let record;
    if(path==='/api/send-verification') {
      record=await user(request,env);
      if(!record) return json({error:'请先登录，再验证邮箱。',code:'LOGIN_REQUIRED'},401);
      if(record.emailVerified) return json({ok:true,message:'你的邮箱已经验证。'});
    } else {
      if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)||email.length>254) return json({error:'请填写有效邮箱。'},400);
      if(!await limited(env,'mail-address:'+await digest(email),3,3600000)) return json({error:'发送请求过于频繁，请稍后重试。'},429);
      record=await db(env).prepare('SELECT id,email FROM users WHERE email=?').bind(email).first();
    }
    if(record) {
      try { await issueAccountToken(env,record,path==='/api/forgot-password'?'reset':'verify',context); }
      catch { return json({error:'邮件暂时无法送达，请稍后重试。',code:'MAIL_DELIVERY_FAILED'},502); }
    }
    return json({ok:true,message:path==='/api/forgot-password'?'若该邮箱已注册，你会收到重设密码的邮件。请检查收件箱及垃圾邮件。':'验证邮件已发送，请检查收件箱及垃圾邮件。'});
  }
  if(!await limited(env,'token-ip:'+ip,15,3600000)) return json({error:'操作过于频繁，请稍后重试。'},429);
  const token=String(body.token||'');
  if(!/^[a-f0-9]{64}$/.test(token)) return json({error:'链接无效或已过期，请重新申请。'},400);
  const reset=path==='/api/reset-password';
  let salt,hash;
  if(reset) {
    const password=body.password;
    if(typeof password!=='string'||password.length<10||password.length>128) return json({error:'密码需为 10–128 个字符。'},400);
    salt=random(); hash=await passwordHash(password,salt);
  }
  const claim=await db(env).prepare('UPDATE auth_tokens SET used_at=? WHERE token_hash=? AND kind=? AND used_at IS NULL AND expires_at>? RETURNING user_id').bind(Date.now(),await digest(token),reset?'reset':'verify',Date.now()).first();
  if(!claim) return json({error:'链接无效、已使用或已过期，请重新申请。'},400);
  if(reset) {
    await db(env).prepare('UPDATE users SET password_hash=?,salt=? WHERE id=?').bind(hash,salt,claim.user_id).run();
    await db(env).prepare('DELETE FROM sessions WHERE user_id=?').bind(claim.user_id).run();
    await db(env).prepare('DELETE FROM auth_tokens WHERE user_id=? AND kind=?').bind(claim.user_id,'reset').run();
    return json({ok:true,message:'密码已更新，其他设备的登录已失效。请使用新密码登录。'},200,{'set-cookie':'__Host-physics_session=; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=0'});
  }
  await db(env).prepare('UPDATE users SET email_verified_at=? WHERE id=?').bind(Date.now(),claim.user_id).run();
  return json({ok:true,message:'邮箱已验证，你可以继续学习。'});
}




const json=(data,status=200,extra={})=>new Response(JSON.stringify(data),{status,headers:{'content-type':'application/json; charset=utf-8','cache-control':'no-store',...extra}});
const hex=b=>Array.from(new Uint8Array(b),x=>x.toString(16).padStart(2,'0')).join('');
const random=()=>hex(crypto.getRandomValues(new Uint8Array(32)));
const digest=async s=>hex(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s)));
async function passwordHash(password,salt){const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']);return hex(await crypto.subtle.deriveBits({name:'PBKDF2',hash:'SHA-256',salt:new TextEncoder().encode(salt),iterations:100000},key,256));}
function constantEqual(a,b){if(a.length!==b.length)return false;let c=0;for(let i=0;i<a.length;i++)c|=a.charCodeAt(i)^b.charCodeAt(i);return c===0;}
const cookie=(token,age=1209600)=>`__Host-physics_session=${token}; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=${age}`;
const db=env=>{if(!env.DB)throw new Error('DATABASE_UNAVAILABLE');return env.DB;};
async function user(request,env){const match=(request.headers.get('cookie')||'').match(/(?:^|;\s*)__Host-physics_session=([a-f0-9]{64})(?:;|$)/);if(!match)return null;const record=await db(env).prepare('SELECT u.id,u.email,u.email_verified_at FROM sessions s JOIN users u ON s.user_id=u.id WHERE s.token_hash=? AND s.expires_at>?').bind(await digest(match[1]),Date.now()).first();return record?{id:record.id,email:record.email,emailVerified:!!record.email_verified_at}:null;}
async function limited(env,key,max,windowMs){const now=Date.now(),bucket=Math.floor(now/windowMs);const row=await db(env).prepare('INSERT INTO limits (key,count,expires_at) VALUES (?,1,?) ON CONFLICT(key) DO UPDATE SET count=count+1 RETURNING count').bind(key+':'+bucket,now+windowMs).first();return row.count<=max;}
const clean=s=>String(s).replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim();
export function retrieve(query,topic){const chars=[...new Set(query.replace(/[^\p{L}\p{N}]/gu,''))],pairs=[];for(let i=0;i<query.length-1;i++)pairs.push(query.slice(i,i+2));return COURSES.map(l=>{const title=l.title,text=clean(title+' '+l.description+' '+l.knowledge.join(' ')+' '+l.formulas.map(f=>f.label+' '+f.equation).join(' '));const score=(l.id===topic?2:0)+(query.includes(title)?30:0)+pairs.filter(c=>text.includes(c)).length*2+chars.filter(c=>title.includes(c)).length;return{lesson:l,score};}).filter(x=>x.score>2).sort((a,b)=>b.score-a.score).slice(0,4).map(x=>x.lesson);}
const stringArray={type:'array',items:{type:'string'}};
const strictObject=properties=>({type:'object',properties,required:Object.keys(properties),additionalProperties:false});
const quantitySchema=strictObject({label:{type:'string'},value:{type:['number','null']},unit:{type:'string'},evidence:{type:'string'}});
const parameterSchema=strictObject({key:{type:'string'},value:{type:'number'},unit:{type:'string'},evidence:{type:'string'}});
const scene3DSchema=strictObject({experiment:{type:'string',enum:['none',...Object.keys(question3DModels)]},parameters:{type:'array',items:parameterSchema},assumptions:stringArray,reason:{type:'string'}});
const solutionSchema=strictObject({answer:{type:'string'},recognizedText:{type:'string'},quantities:{type:'array',items:quantitySchema},simulation:strictObject({model:{type:'string',enum:['none',...Object.keys(problemModels)]},parameters:{type:'array',items:parameterSchema},assumptions:stringArray,reason:{type:'string'}}),scene3d:scene3DSchema});
export function validateImage(value){if(typeof value!=='string'||value.length>2100000)return false;const match=value.match(/^data:image\/(png|jpeg|webp);base64,([A-Za-z0-9+/]+={0,2})$/);if(!match||match[2].length%4)return false;try{const head=atob(match[2].slice(0,24));return match[1]==='png'?head.startsWith('\x89PNG\r\n\x1a\n'):match[1]==='jpeg'?head.startsWith('\xff\xd8\xff'):head.startsWith('RIFF')&&head.slice(8,12)==='WEBP';}catch{return false;}}
export function normalizeSimulation(value){if(!value||!problemModels[value.model])return{model:'none',parameters:{},assumptions:[],reason:typeof value?.reason==='string'?value.reason:'当前模型不适合这个过程。'};const model=problemModels[value.model],parameters={},seen=new Set(),assumptions=Array.isArray(value.assumptions)?value.assumptions.filter(x=>typeof x==='string').slice(0,8):[];for(let input of Array.isArray(value.parameters)?value.parameters:[]){if(!input||typeof input!=='object')continue;input={...input,key:canonicalParameterKey(input.key),unit:canonicalPhysicsUnit(input.unit)};if(seen.has(input.key)){delete parameters[input.key];assumptions.push('发现重复参数，请在数据卡核对。');continue;}seen.add(input.key);const field=model.fields.find(f=>f.key===input.key);if(!field||input.unit!==field.unit||typeof input.value!=='number'||!Number.isFinite(input.value)||input.value<field.min||input.value>field.max){assumptions.push('有参数的单位或范围未通过检查，请在数据卡补充。');continue;}parameters[input.key]=input.value;}return{model:value.model,parameters,assumptions,reason:typeof value.reason==='string'?value.reason:'请核对题目数据。',evidence:Array.isArray(value.parameters)?value.parameters.filter(p=>p&&typeof p.evidence==='string').map(p=>p.key+'：'+p.evidence).slice(0,12):[]};}
export function aiConfiguration(env){const provider=env.AI_PROVIDER||(env.QWEN_API_KEY?'qwen':'openai'),ready=provider==='qwen'?!!(env.QWEN_API_KEY&&env.QWEN_BASE_URL&&env.QWEN_MODEL):!!env.OPENAI_API_KEY;return{provider,key:provider==='qwen'?env.QWEN_API_KEY:env.OPENAI_API_KEY,ready,visionReady:ready&&(provider!=='qwen'||!!env.QWEN_VISION_MODEL)};}
export function qwenEndpoint(base){const url=new URL(base);if(url.protocol!=='https:'||url.username||url.password||url.search||url.hash)throw new Error('INVALID_API_BASE');url.pathname=url.pathname.replace(/\/$/,'');if(!url.pathname.endsWith('/chat/completions'))url.pathname+='/chat/completions';return url.href;}
